import React, { useState } from "react";
import {extractProductFromAllProducts, isAllowedByMenuStopForSelection} from "../../../utils/menuStop";
import {applyMenuStopOrderFeedback} from "../../../utils/menuStopOrderFeedback";
import {
    Alert,
    Modal,
    StyleSheet,
    Text,
    Pressable,
    View,
    Button,
    FlatList,
    Platform,
    TouchableOpacity,
    SafeAreaView,
    ScrollView,
    Dimensions, TextInput
} from "react-native";
import {THEME} from "../../../theme";
import {AntDesign, Ionicons} from '../../../components/SystemIcons';
import {useDispatch, useSelector} from "react-redux";
import {
    loadProductScreen,
    loadSlideHeader,
    setCitySystem,
    loadCatalogProduct,
    loadSlideHeaderStatus,
    setCityUserSystemPhone,
    setModalStatus,
    setDefaultStateOrder,
    loadAuthInfo,
    setActiveOrderScreenData
} from "../../../store/actions/post";
import { MaterialIcons } from '../../../components/SystemIcons';
import SwipeUpDown from 'react-native-swipe-up-down';
import ModalPage from "../../../templateComponents/ModalPage/ModalPage";
import {RecivingOrder} from "./Receiving";
import {PaymentType} from "./PaymentType";
import {PointsBlock} from "./PointsBlock";
import {ButtonEbee} from "../../../templateComponents/Button/ButtonEbee";
import {NumberFormatPrice} from "../../../templateComponents/NumberFormat/NumberFormat";
import {Group} from "../../../templateComponents/Group/GroupMain";
import {ServerDB} from "../../../serverDb";
import {GetAllPriceBasketPreorderToppingSum} from "../GetAllPriceBasketLimitTopping";
// import {ModulInformerWorkTimeInBasket} from "../../../templateComponents/InformerWorkTimeBasket/ModulInformerWorkTimeInBasket";
import {ACTIVE_ORDER_SCREEN_RELOAD, REMOVE_POST} from "../../../store/types";
import {getTypeDevice} from "../../../templateComponents/GetTypeDeviceSize/GetTypeDeviceSize";
import {InfoBottomBlock} from "../infoBottomBlock/InfoBottomBlock";
import {CallOperator} from "./callOperator";
import {CheckWorkTimeAffiliateNew} from "../../CheckWorkTimeAffiliateNew";
import {ChangeAmount} from "./ChangeAmount";
import {ServiceFee} from "../../../templateComponents/ServiceFee/SeviceFee";
import {calculateDelivery} from "../../../utils/dynamicDelivery";
import {DynamicDeliveryInfo} from "../../DynamicDelivery/DynamicDeliveryInfo";



export const OrderModal = ({navigation,titleCity,keys,route,liveBasketSum = null}) => {
    const [modalVisible, setModalVisible] = useState(true);
    const dispatch = useDispatch();
    const StatusModal = useSelector(state=>state.post.modalStateStatus.MODAL_ORDER);
    const CityData = useSelector(state=>state.post.cityData.cityId);
    const StatusAllModal = useSelector(state=>state.post.modalStateStatus);

    const statusDelivery = useSelector(state=>state.post.typeDeliverySystem);
    const AffiliateData = useSelector(state=>state.post.affiliateSelect);
    const {isPickup, openNow: pickupOpenNow} = usePickupAvailability();
    const AdresData = useSelector(state=>state.post.adressSelect);

    // const [komment,setKomment] = useState(null);
    const komment = useSelector(state=>state.post.textKomment);

    const sumItogBasketState = useSelector(state => state.post.basketSum);
    const sumItogBasket = liveBasketSum === null ? sumItogBasketState : Number(liveBasketSum || 0);
    const sumDiscountPromokode = useSelector(state => state.post.dataPromokodeDiscoun.allSumDiscount);
    const bonusPointsAffectDelivery = useSelector(state => state.post.bonusPointsAffectDelivery);
    const allPointsSaleGlobal = useSelector(state => state.post.allPointsSale);

    const BDayBasket = useSelector(state => state.post.BDay); // статус др: тру в промежутке +-3 дня фолс нет
    const BDayManualOff = useSelector(state => state.post.BDayManualOff);
    const BDayDiscountBasket = useSelector(state => state.post.BDayDiscount);//
    const BDayPrice = useSelector(state => state.post.BDayPrice)
    const BDayActive = BDayBasket.BDay === true && BDayManualOff === false;

    const DopProductList = useSelector(state => state.post.AllDopProduct);
    const DataPromokodeDiscountProduct = useSelector(state => state.post.dataPromokodeDiscoun);
    const ThreeForTwoListProduct = useSelector(state => state.post.ThreeForTwoListProduct);
    const AdresList = useSelector(state => state.post.adressAffiliate.list);
    const ListAdresForRender = Object.keys(AdresList).map(
        (id,n)=>{
            return AdresList[id]
        }
    );

    const getActiveAffiliate = (Title,DataDay)=>{
        let activeAf = false;
        activeAf = CheckWorkTimeAffiliateNew(DataDay.hoursStart,DataDay.minuteStart,DataDay.hoursStop,DataDay.minuteStop);
        return activeAf;
    };

    const getAllPointsWorkStatus = ()=>{
        if (isPickup) {
            return pickupOpenNow || (preorderData.dateDelivery && preorderData.dateDelivery !== 0) ? "go" : "stop";
        }
        let StatusWorkAllPoints = "stop";
        ListAdresForRender.forEach((d,n)=>{
            let StatusWorkAffiliate = getActiveAffiliate(d.title,d.worktime.days[new Date().getDay()]);
            if(StatusWorkAffiliate === true){
                StatusWorkAllPoints = "go";
            }
        });

        if(preorderData.dateDelivery !== 0 ){StatusWorkAllPoints = "go";}
        // alert(StatusWorkAllPoints);
        return StatusWorkAllPoints;
    };

    const deliveryCalculation = calculateDelivery(
        AdresData?.diliveryData,
        sumItogBasket,
        allPointsSaleGlobal,
        bonusPointsAffectDelivery
    );
    const minSumOrder = statusDelivery === true ? Number(AdresData?.diliveryData?.min_sum_order || 0) : 0;
    const dynamicFreeRange = deliveryCalculation.ranges.find((range) => range.price === 0) || null;
    const minSumOrderFree = statusDelivery === true
        ? (deliveryCalculation.dynamic ? dynamicFreeRange?.from ?? null : Number(AdresData?.diliveryData?.min_sum_free_dilivery || 0))
        : null;
    const sumDeliveryOrder = statusDelivery === true ? deliveryCalculation.price : 0;
    const sumDeliveryOrderW = statusDelivery === true ? deliveryCalculation.amountToFree : 0;


    const DateValueShow = useSelector(state=>state.post.preorderData.dateDelivery);
    const TimeValueShow = useSelector(state=>state.post.preorderData.timeDelivery);


    let [animateModal, setanimateModal] = useState(false);

    ///////Данные для отправуи на сервер

    const basket = useSelector(state => state.post.basket);
    const basketTopping = useSelector(state => state.post.basketTopping);
    const idUserSystem = useSelector(state => state.post.AuthUserData.id);

    const promokodeActive = useSelector(state => state.post.promokodeActive);
    const promokodeData = useSelector(state => state.post.promokodeData);
    const dataPromokodeDiscoun = useSelector(state => state.post.dataPromokodeDiscoun);

    const typePayment = useSelector(state => state.post.typePayment);
    const changeAmount = useSelector(state => state.post.changeAmount);

    const callOperator = useSelector(state => state.post.callOperator);
    const personCount = useSelector(state => state.post.personCount);
    const personCountActive = useSelector(state => state.post.personCountActive);
    const preorderData = useSelector(state => state.post.preorderData);
    const commentOrder = useSelector(state => state.post.commentOrder);


    const PromokodeErrorInfo = useSelector(state=> state.post.promokodeErrorInfo);

    const PreorderCategoryDopsLimit = useSelector(state => state.post.PreorderCategoryDopsLimit.list);
    const allProducts = useSelector(state => state.post.allProducts);
    const BonusPointsActive = useSelector(state => state.post.bonusPointsActive);
    const typeDeviceVK = useSelector(state => state.post.typeDeviceVK);
    const ServiceFeeSum = useSelector(state => state.post.ServiceFeeSum);
    const ServiceFeeS = useSelector(state => state.post.ServiceFee);




    let sumItogBasketCheckDiscount = 0;

    if(PromokodeErrorInfo.showIconError === true) {
        sumItogBasketCheckDiscount = sumItogBasket;
    }else{
        if(promokodeActive){
            // sumItogBasketCheckDiscount = sumItogBasket-sumDiscountPromokode;
            sumItogBasketCheckDiscount = sumItogBasket;
        }else{
            sumItogBasketCheckDiscount = sumItogBasket;
        }
    }

    const activeGift = useSelector(state => state.post.activeGift);



    const blockedByMenuStop = basket.some(row => (row.type || []).some(type =>
        !isAllowedByMenuStopForSelection(
            extractProductFromAllProducts(allProducts, type.categoryId, row.id), preorderData
        )
    ));

    const [orderError, setOrderError] = useState("");
    const [orderErrorProducts, setOrderErrorProducts] = useState([]);
    const handleSetOrderServer = async ()=>{
        setOrderError("");
        setOrderErrorProducts([]);
        if (blockedByMenuStop) {
            handleSetStatusModal("MODAL_ORDER_PRELOADER", false);
            return;
        }
        let sumPreorderTopping = GetAllPriceBasketPreorderToppingSum(PreorderCategoryDopsLimit,basket,allProducts,dataPromokodeDiscoun);
        let typePaymentSet = typePayment;
        if(typePayment == 3){
            typePaymentSet = 0;
        }
        let ArrayOrder = {
            'clientCapabilities':{
                'dynamicDelivery':1,
                'menuStopValidation':1
            },
            'callOperator':callOperator,
            'countPerson': personCountActive ? personCount : 1,
            "typeOrderDevice":6,
            "basketData": {
                'basket': basket,
                'basketTopping': basketTopping,
            },
            "userData":{
                'idUser':idUserSystem,
            },
            "orderData":{
                'typePayment':typePaymentSet,
                'changeAmount':changeAmount,
                'allPointsSale':allPointsSaleGlobal,
                'sumItog':(sumItogBasketCheckDiscount*1)+(sumDeliveryOrder*1),
                'sumProductsForDelivery':deliveryCalculation.calculationSum,
                'sumDiscountPromokode':sumDiscountPromokode,
                'commentOrder':komment,
                'sumPreorderTopping':sumPreorderTopping,
                'ServiceFeeSum':{...ServiceFeeS,...{"calculated":ServiceFeeSum}}
            },
            "deliveryData":{
                'typeDelivery':statusDelivery,
                'adresDelivery':AdresData,
                'adresAffiliate':AffiliateData,
                'priceDelivery':sumDeliveryOrder,
                'deliveryApiId':deliveryCalculation.apiId,
                'preorderData':preorderData
            },
            "promokodeData":{
                'promokodeActive':promokodeActive,
                'showIconError':PromokodeErrorInfo.showIconError,
                'promokodeData':promokodeData,
                'dataPromokodeDiscoun':dataPromokodeDiscoun
            },
            "giftData":activeGift,
            "BDayData":{
                "BDayStatus":BDayActive,
                "BDayDiscount":BDayDiscountBasket,
                "BDayPrice":BDayPrice
            }
        };


        let ResultOrder;
        try {
            ResultOrder = await ServerDB.setOrderServer(CityData,idUserSystem,ArrayOrder);
        } catch (error) {
            ResultOrder = {error:true,errorInfo:"Не удалось отправить заказ. Проверьте соединение и повторите попытку"};
        }
        if (ResultOrder?.error || !ResultOrder?.orderId) {
            applyMenuStopOrderFeedback(ResultOrder, {cityId:CityData, preorder:preorderData, delivery:statusDelivery, affiliate:AffiliateData}, dispatch);
            setOrderErrorProducts(Array.isArray(ResultOrder?.blockedProducts) ? ResultOrder.blockedProducts : []);
            setOrderError(ResultOrder?.errorInfo || "Заказ не принят. Проверьте доступность товаров и выбранное время");
            handleSetStatusModal("MODAL_ORDER_PRELOADER", false);
            handleSetStatusModal("MODAL_ORDER", false);
            return;
        }

        await dispatch(setDefaultStateOrder());
        await dispatch(loadAuthInfo( false, false, null,  false, null, {}, idUserSystem));

        if(ResultOrder.onlineModal === true){
            window.location.hash = 'OnlinePayments';
            navigation.navigate('OnlinePayments', {
                title: 'Онлайн оплата заказа №'+ResultOrder.orderId,
                idOrder:ResultOrder.orderId*1,
                sumPayment:ResultOrder.sumPayment,
                idPointsPaymentToken:ResultOrder.idPointsPaymentToken
            });
        }else {
            let statusReloadOrderScreen = await dispatch(setActiveOrderScreenData(ResultOrder.orderId,true));
            window.location.hash = 'OrderListProfile';
            navigation.navigate('OrderListProfile', {
                title: 'Список заказов',
                productData: [],
                idOrderNow: ResultOrder.orderId,
                reloads: true
            });
        }

        handleSetStatusModal("MODAL_ORDER_PRELOADER", false);

    };


    ////////



    const getSumSalePoints = (allSum,allPoints)=> {
            let itog = 0;

            itog = allSum - allPoints;
            if (itog < 0) {
                itog = 0;
            }

            return itog;
        }
    ;

    const handleSetStatusModal = (nameModal,status)=>{
        dispatch(setModalStatus(nameModal,status));
    };

    const FlatListData = [
        <View style={styles.modalContent}>


            {/*<ModulInformerWorkTimeInBasket navigation={navigation} route={route}/>*/}

            <View style={styles.TitleModal} key={"PaymentBlock"}>
                <Text style={styles.modalTextTitle}>Оплата</Text>
            </View>
            <View style={styles.ChildModal} key={"DeliveryPayment"}>
                <View style={styles.ChildBlock}>
                    <RecivingOrder navigation={navigation} route={route}/>
                </View>
                {/*<View style={styles.ChildBlock} key={"CallOperatorBlock"}>*/}
                {/*    <Text style={styles.titleChildBlock}>Звонок оператора</Text>*/}
                {/*    <CallOperator/>*/}
                {/*</View>*/}
                <View style={styles.ChildBlock} key={"PaymentTypeBlock"}>
                    <Text style={styles.titleChildBlock}>Способ оплаты</Text>
                    <PaymentType/>
                </View>
                {typePayment === 1 ? <View style={styles.ChildBlock} key={"KeepChangeBlock"}>
                    <Text style={styles.titleChildBlock}>С какой купюры приготовить сдачу</Text>
                    <ChangeAmount/>
                </View> : false }
                {BonusPointsActive === true ?
                <View style={styles.ChildBlock} key={"PointSaleBlock"}>
                    <Text style={styles.titleChildBlock}>Списание бонусов</Text>
                    <PointsBlock/>
                </View>
                    : false
                }
                {/*<View style={styles.ChildBlock} key={"PointSaleBlock"}>*/}
                {/*    <Text style={styles.titleChildBlock}>Комментарий к заказу</Text>*/}
                {/*    <TextInput*/}
                {/*        editable*/}
                {/*        style={styles.inputKomments}*/}
                {/*        onChangeText={setKomment}*/}
                {/*        value={komment}*/}
                {/*    />*/}
                {/*</View>*/}
                <View style={styles.ChildBlock} key={"NoneBlock"}>
                </View>
            </View>
        </View>,

    ];

    const getOkOrderButtonDateDelivery = ()=>{
        if (isPickup) {
            if (!DateValueShow || DateValueShow === 0) return isPickupOpenAt(AffiliateData);
            return TimeValueShow !== 0 && isPickupSlotOpen(AffiliateData, DateValueShow, TimeValueShow);
        }
        if(DateValueShow === 0){
            return true;
        }else{
            if(TimeValueShow === 0){
                return false;
            }else{
                return true;
            }
        }
    };



    return (
        <>
        <ModalPage
            webZIndex={9998}
            gesturesDisabled={!!(StatusAllModal.MODAL_DATE_DELIVERY || StatusAllModal.MODAL_TIME_DELIVERY)}
            modalVisible={StatusModal}
            PressToanimate={animateModal}
            ContentModal={
                <View
                    scrollEnabled={false}
                    style={styles.containerContent}
                >
                    <FlatList
                        style={{flex: 1, minHeight: 0}}
                        contentContainerStyle={{paddingBottom: 8}}
                        data={FlatListData}
                        listKey={(item,n)=>"ModalContent_Order_"+n}
                        renderItem={({item, index}) => (
                            item
                        )}
                        keyExtractor={(item,n) => "OrderModalContent_"+n}
                    />
                    <Group
                        styles={{
                            // Итоги занимают свою высоту, а список прокручивается над ними.
                            flexShrink:0,
                            backgroundColor:"#ffffff",
                            // paddingBottom: "10%", старое значение
                            paddingBottom: typeDeviceVK == 'mobile_iphone' ? "5%" : "5%",
                            width:"100%",
                            paddingHorizontal:"3%"
                        }} shadow={false}
                    >
                            <InfoBottomBlock
                                productBasketAll={basket}
                                allProducts={allProducts}
                                basketTopping={basketTopping}
                                DopProductList={DopProductList}
                                discountSum={DataPromokodeDiscountProduct.allSumDiscount}
                                sumDeliverys={sumDeliveryOrder}
                                ThreeForTwoListProduct={ThreeForTwoListProduct}
                                getOneSumDiscount={true}
                            />
                        {statusDelivery === true ?
                            <>
                                <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                    <Text >Стоимость заказа</Text>
                                    <Text >{NumberFormatPrice(getSumSalePoints(sumItogBasketCheckDiscount,allPointsSaleGlobal),0,'.',' ')} ₽</Text>
                                </View>
                                {!deliveryCalculation.dynamic && sumDeliveryOrder && sumDeliveryOrderW !== null ?
                                    <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                        <Text style={{color:THEME.INFO_COLOR}}>Для бесплатной доставки не хватает</Text>
                                        <Text style={{color:THEME.INFO_COLOR}}>{NumberFormatPrice(sumDeliveryOrderW,0,'.',' ')} ₽</Text>
                                    </View>
                                    :
                                    false
                                }
                                {deliveryCalculation.dynamic ?
                                    <DynamicDeliveryInfo calculation={deliveryCalculation} variant="summary"/>
                                    :
                                    <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                        <Text>Стоимость доставки</Text>
                                        <Text>{NumberFormatPrice(sumDeliveryOrder,0,'.',' ')} ₽</Text>
                                    </View>}
                                {ServiceFeeS ?
                                <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                    <Text>Сервисный сбор</Text>
                                    <Text><ServiceFee sumOrder={(sumItogBasketCheckDiscount*1)+(sumDeliveryOrder*1)-allPointsSaleGlobal}/> ₽</Text>
                                </View>
                                    : false }
                                <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                    <Text style={styles.titleChildBlock}>Итого</Text>
                                    <Text style={styles.titleChildBlock}>{NumberFormatPrice((sumItogBasketCheckDiscount*1)+(sumDeliveryOrder*1)-allPointsSaleGlobal+(ServiceFeeSum*1),0,'.',' ')} ₽</Text>
                                </View>
                            </>
                            :
                            <View style={[styles.ChildBlock2,{flexDirection: "row",justifyContent:"space-between",alignItems:"center",marginVertical:0}]}>
                                <Text style={styles.titleChildBlock}>Стоимость заказа</Text>
                                <Text style={styles.titleChildBlock}>{NumberFormatPrice(getSumSalePoints(sumItogBasketCheckDiscount,allPointsSaleGlobal),0,'.',' ')} ₽</Text>
                            </View>
                        }

                        {
                            blockedByMenuStop ?
                            <Text style={{color:THEME.DANGER_COLOR, paddingVertical:10}}>
                                Часть товаров недоступна на выбранное время. Измените дату и время или удалите эти товары из корзины.
                            </Text> :
                            (getAllPointsWorkStatus()) === "go" ?
                            (sumItogBasket)>=minSumOrder ?
                            <ButtonEbee
                                onPress={()=>{
                                    if((sumItogBasket)>=minSumOrder) {
                                        if(getOkOrderButtonDateDelivery()){
                                            if (![1, 2, 3].includes(typePayment)) {
                                                Alert.alert('Способ оплаты', 'Выберите способ оплаты заказа');
                                                return;
                                            }
                                            setanimateModal(true);
                                            handleSetStatusModal("MODAL_ORDER", false);
                                            handleSetStatusModal("MODAL_ORDER_PRELOADER", true);
                                            handleSetOrderServer();
                                        }
                                    }else{
                                        Alert.alert('Заказ не принят','Сумма Вашего заказа меньше, чем минимальная стоимость приема заказа ('+minSumOrder+'р). Добавьте в корзину еще товаров.'+(minSumOrderFree !== null ? '\nБесплатная доставка от '+minSumOrderFree+'р' : ''));
                                    }
                                }}
                                size="xl"
                                borderRadius={20}
                                shadow={false}
                                active={
                                    (sumItogBasket)>=minSumOrder ?
                                        getOkOrderButtonDateDelivery()
                                        :
                                        false
                                }
                            >
                                Оформить заказ
                            </ButtonEbee>
                            :
                            <View style={{textAlign:"center",backgroundColor:"#eeeeee",borderRadius:10,paddingVertical:5}}>
                                <View style={{textAlign:"center"}}><Text style={{textAlign:"center"}}>Минимальная сумма заказа на этот адрес, без учета платной доставки составляет: <Text style={{fontFamily:"open-bold, segoe ui, Arial", fontWeight:700,}}>{NumberFormatPrice(minSumOrder,0, '.',' ')} ₽</Text></Text></View>
                                <View style={{textAlign:"center"}}><Text style={{textAlign:"center"}}>Для совершения заказа нужно еще: <Text style={{fontFamily:"open-bold, segoe ui, Arial", fontWeight:700,}}>{NumberFormatPrice(minSumOrder-(sumItogBasket),0, '.',' ')} ₽</Text></Text></View>
                            </View>
                                    :
                                <View style={{textAlign:"center",backgroundColor:"#eeeeee",borderRadius:10,paddingVertical:5}}>
                                    <View style={{textAlign:"center"}}><Text style={{textAlign:"center"}}>К сожалению мы уже не принимаем заказы</Text></View>
                                    <View style={{textAlign:"center"}}><Text style={{textAlign:"center"}}>Вы можете оставить предзаказ, а мы начнем его готовить как откроемся!</Text></View>
                                </View>
                        }
                    </Group>
                </View>
            }
            HeaderStyle={styles.headerContent}
            ContentModalStyle={styles.Modal}
            HeaderContent={
                <View style={styles.containerHeader}>
                    <View style={getTypeDevice(Dimensions.get('window').width,Dimensions.get('window').height) === false ? styles.topIndicatorWeb : Dimensions.get('window').width >460 ? styles.topIndicatorWeb : styles.topIndicator}>
                        {/*{Dimensions.get('window').width >= 421 ? */}
                        {/*    <ButtonEbee*/}
                        {/*    onPress={()=>{*/}
                        {/*        handleSetStatusModal("MODAL_ORDER",false);*/}
                        {/*        //setModalVisible(!modalVisible);*/}
                        {/*        setanimateModal(false);*/}
                        {/*    }}*/}
                        {/*    size={'l'}*/}
                        {/*    borderRadius={20}*/}
                        {/*>*/}
                        {/*    Закрыть*/}
                        {/*</ButtonEbee>*/}
                        {/*    : */}
                        {/*    false}*/}
                        {getTypeDevice(Dimensions.get('window').width,Dimensions.get('window').height) === false ?
                            <AntDesign name="closecircleo" size={20} color={THEME.MAIN_COLOR}
                                       onPress={()=>{
                                           handleSetStatusModal("MODAL_ORDER",false);
                                           //setModalVisible(!modalVisible);
                                           setanimateModal(false);
                                       }}
                                       style={{
                                           alignSelf:'end',
                                           // paddingRight:'2%',
                                           paddingTop:10,
                                           // paddingRight:15
                                       }}
                            />
                            : Dimensions.get('window').width >460 ?
                            <AntDesign name="closecircleo" size={20} color={THEME.MAIN_COLOR}
                                       onPress={()=>{
                                           handleSetStatusModal("MODAL_ORDER",false);
                                           //setModalVisible(!modalVisible);
                                           setanimateModal(false);
                                       }}
                                       style={{
                                           alignSelf:'end',
                                           // paddingRight:'2%',
                                           paddingTop:10,
                                           // paddingRight:15
                                       }}
                            />
                            :
                            false}
                    </View>
                </View>
            }
            onClose={() => {
                handleSetStatusModal("MODAL_ORDER",false);
                //setModalVisible(!modalVisible);
                setanimateModal(false);
            }}

        />
        {!!orderError && <Modal
            visible
            transparent
            animationType="fade"
            onRequestClose={() => setOrderError("")}
        >
            <View style={styles.orderErrorOverlay}>
                <View style={styles.orderErrorCard} accessibilityViewIsModal>
                    <Text style={styles.orderErrorTitle}>{orderErrorProducts.length ? 'Товары недоступны' : 'Не удалось оформить заказ'}</Text>
                    <ScrollView style={{flexShrink:1,marginBottom:20}} showsVerticalScrollIndicator>
                        <Text style={styles.orderErrorText} accessibilityRole="alert">{orderError}</Text>
                        {orderErrorProducts.map((product, index) => (
                            <View key={String(product.id) + ':' + index} style={styles.orderErrorProduct}>
                                <Text style={styles.orderErrorProductNumber}>{index + 1}.</Text>
                                <View style={{flex:1,minWidth:0}}>
                                    <Text style={styles.orderErrorProductTitle}>{product.title}</Text>
                                    {product.reason === 'removed' && <Text style={styles.orderErrorText}>Больше нет в меню</Text>}
                                </View>
                            </View>
                        ))}
                    </ScrollView>
                    <TouchableOpacity
                        accessibilityRole="button"
                        onPress={() => setOrderError("")}
                        style={[styles.orderErrorButton, {backgroundColor:THEME.MAIN_COLOR}]}
                    >
                        <Text style={{color:'#fff',fontSize:15,fontWeight:'600'}}>Понятно</Text>
                    </TouchableOpacity>
                </View>
            </View>
        </Modal>}
        </>
    );
};

