import React, {useState} from 'react';
import {Modal, Pressable, ScrollView, StyleSheet, Text, View} from 'react-native';
import {AntDesign, MaterialCommunityIcons} from '../../components/SystemIcons';
import {THEME} from '../../theme';

const money = (value) => `${Math.round(Number(value) || 0).toLocaleString('ru-RU')} ₽`;

const getHint = (calculation) => {
    if (!calculation.nextRange) {
        return calculation.price === 0 ? 'Бесплатная доставка уже доступна' : 'Текущий тариф действует дальше';
    }
    const nextPrice = calculation.nextRange.price === 0
        ? 'бесплатной доставки'
        : `доставки за ${money(calculation.nextRange.price)}`;
    return `Добавьте товаров ещё на ${money(calculation.amountToNext)} для ${nextPrice}`;
};

const getShortHint = (calculation) => {
    if (!calculation.nextRange) {
        return calculation.price === 0 ? 'Бесплатная доставка уже доступна' : 'Этот тариф действует дальше';
    }
    const nextPrice = calculation.nextRange.price === 0 ? 'бесплатной доставки' : `доставки за ${money(calculation.nextRange.price)}`;
    return `Добавьте ещё ${money(calculation.amountToNext)} для ${nextPrice}`;
};

const getNextDeliveryLabel = (calculation) => calculation.nextRange?.price === 0
    ? 'для бесплатной доставки'
    : `для доставки за ${money(calculation.nextRange?.price)}`;

const DeliveryScale = ({calculation, labels = true, dense = false}) => (
    <View style={[styles.scale, dense ? styles.scaleDense : null]}>
        {calculation.ranges.map((range, index) => {
            let progress = 0;
            if (index < calculation.currentIndex) {
                progress = 100;
            } else if (index === calculation.currentIndex) {
                progress = range.to === null
                    ? 100
                    : Math.max(4, Math.min(100, ((calculation.calculationSum - range.from) / Math.max(1, range.to - range.from + 1)) * 100));
            }
            const compressed = calculation.ranges.length >= 5 && index < calculation.currentIndex;
            return (
                <View key={`${range.from}-${index}`} style={[styles.scaleStep, dense ? styles.scaleStepDense : null, {flex: compressed ? 0.55 : 1}]}>
                    <View style={[styles.scaleTrack, dense ? styles.scaleTrackDense : null]}>
                        <View style={[styles.scaleFill, {width: `${progress}%`, opacity: index < calculation.currentIndex ? 0.35 : 1, backgroundColor: THEME.MAIN_COLOR}]}/>
                    </View>
                    {labels ?
                        <Text numberOfLines={1} style={[styles.scaleLabel, index < calculation.currentIndex ? styles.scaleLabelPassed : null]}>
                            {range.price === 0 ? '0 ₽' : money(range.price)}
                        </Text>
                        : null}
                </View>
            );
        })}
    </View>
);

const AddressInfo = ({calculation, onPress}) => (
    <Pressable onPress={onPress} style={({pressed}) => [styles.addressInfo, pressed ? styles.cardPressed : null]}>
        <View style={styles.addressInfoRow}>
            <MaterialCommunityIcons name="truck-delivery-outline" size={17} color={THEME.MAIN_COLOR}/>
            <Text style={styles.addressLabel}>Доставка сейчас</Text>
            <Text style={[styles.addressPrice, {color: THEME.MAIN_COLOR}]}>{calculation.price === 0 ? 'Бесплатно' : money(calculation.price)}</Text>
            <AntDesign name="right" size={11} color={THEME.MAIN_COLOR}/>
        </View>
        <Text numberOfLines={1} style={styles.addressHint}>{getShortHint(calculation)}</Text>
        <DeliveryScale calculation={calculation} labels={false} dense/>
    </Pressable>
);

const SelectorInfo = ({calculation, onPress}) => (
    <Pressable onPress={onPress} style={({pressed}) => [styles.selectorInfo, pressed ? styles.cardPressed : null]}>
        {calculation.nextRange ?
            <View style={styles.selectorHintRow}>
                <Text numberOfLines={1} style={styles.selectorHint}>Добавьте ещё {money(calculation.amountToNext)}</Text>
                <Text numberOfLines={1} style={styles.selectorHintRight}>{getNextDeliveryLabel(calculation)}</Text>
            </View>
            : <Text numberOfLines={1} style={styles.selectorHint}>{getShortHint(calculation)}</Text>}
        <DeliveryScale calculation={calculation} labels={false} dense/>
    </Pressable>
);

const SummaryInfo = ({calculation, onPress}) => (
    <Pressable onPress={onPress} style={({pressed}) => [styles.summaryInfo, pressed ? styles.cardPressed : null]}>
        <View style={styles.summaryRow}>
            <View style={styles.summaryTitleRow}>
                <Text style={styles.summaryTitle}>Стоимость доставки</Text>
                <AntDesign name="infocirlceo" size={12} color={THEME.MAIN_COLOR} style={{marginLeft: 5}}/>
            </View>
            <Text style={[styles.summaryPrice, {color: THEME.MAIN_COLOR}]}>{calculation.price === 0 ? 'Бесплатно' : money(calculation.price)}</Text>
        </View>
        <Text numberOfLines={1} style={styles.summaryHint}>{getShortHint(calculation)}</Text>
        <DeliveryScale calculation={calculation} labels={false} dense/>
    </Pressable>
);

export const DynamicDeliveryInfo = ({calculation, compact = false, title = 'Доставка', variant = 'card', renderTrigger}) => {
    const [detailsVisible, setDetailsVisible] = useState(false);
    if (!calculation || !calculation.dynamic) {
        return null;
    }

    return (
        <>
            {renderTrigger ? renderTrigger(() => setDetailsVisible(true)) : variant === 'address' ?
                <AddressInfo calculation={calculation} onPress={(event) => {
                    if (event && typeof event.stopPropagation === 'function') event.stopPropagation();
                    setDetailsVisible(true);
                }}/>
                : variant === 'selector' ?
                    <SelectorInfo calculation={calculation} onPress={(event) => {
                        if (event && typeof event.stopPropagation === 'function') event.stopPropagation();
                        setDetailsVisible(true);
                    }}/>
                : variant === 'summary' ?
                    <SummaryInfo calculation={calculation} onPress={(event) => {
                        if (event && typeof event.stopPropagation === 'function') event.stopPropagation();
                        setDetailsVisible(true);
                    }}/>
                    : <Pressable
                onPress={(event) => {
                    if (event && typeof event.stopPropagation === 'function') {
                        event.stopPropagation();
                    }
                    setDetailsVisible(true);
                }}
                style={({pressed}) => [styles.card, compact ? styles.cardCompact : null, pressed ? styles.cardPressed : null]}
            >
                <View style={styles.headingRow}>
                    <View style={styles.titleRow}>
                        <MaterialCommunityIcons name="truck-delivery-outline" size={compact ? 18 : 20} color={THEME.MAIN_COLOR}/>
                        <Text style={styles.title}>{title}</Text>
                    </View>
                    <Text style={[styles.price, {color: THEME.MAIN_COLOR}]}>{calculation.price === 0 ? 'Бесплатно' : money(calculation.price)}</Text>
                </View>
                <DeliveryScale calculation={calculation}/>
                <View style={styles.hintRow}>
                    <Text style={styles.hint}>{getHint(calculation)}</Text>
                    <AntDesign name="right" size={12} color={THEME.MAIN_COLOR}/>
                </View>
                    </Pressable>}

            {detailsVisible ? <Modal transparent animationType="fade" visible onRequestClose={() => setDetailsVisible(false)}>
                <Pressable style={styles.overlay} onPress={() => setDetailsVisible(false)}>
                    <Pressable style={styles.modalCard} onPress={() => {}}>
                        <View style={styles.modalHeader}>
                            <View style={styles.titleRow}>
                                <MaterialCommunityIcons name="truck-delivery-outline" size={23} color={THEME.MAIN_COLOR}/>
                                <Text style={styles.modalTitle}>Условия доставки</Text>
                            </View>
                            <Pressable onPress={() => setDetailsVisible(false)} hitSlop={10}>
                                <AntDesign name="close" size={21} color="#4b5563"/>
                            </Pressable>
                        </View>
                        <Text style={styles.modalSummary}>
                            Сейчас: {calculation.price === 0 ? 'бесплатная доставка' : money(calculation.price)}
                        </Text>
                        <DeliveryScale calculation={calculation}/>
                        <ScrollView style={styles.rangesList}>
                            {calculation.ranges.map((range, index) => (
                                <View key={`${range.from}-details-${index}`} style={[styles.rangeRow, index === calculation.currentIndex ? [styles.rangeRowActive, {borderColor: THEME.MAIN_COLOR}] : null]}>
                                    <View>
                                        <Text style={styles.rangeTitle}>
                                            От {money(range.from)}{range.to === null ? '' : ` до ${money(range.to)}`}
                                        </Text>
                                    </View>
                                    <Text style={[styles.rangePrice, {color: THEME.MAIN_COLOR}]}>{range.price === 0 ? 'Бесплатно' : money(range.price)}</Text>
                                </View>
                            ))}
                        </ScrollView>
                        <Text style={styles.modalHint}>{getHint(calculation)}</Text>
                    </Pressable>
                </Pressable>
            </Modal> : null}
        </>
    );
};

