const sections = [
    ['Catalog', 'Меню', 'utensils'], ['Basket', 'Корзина', 'shopping-bag'],
    ['SalesInfo', 'Акции', 'star'], ['InfoDelivery', 'Доставка и оплата', 'map-marker-alt'],
    ['ProfileScreen', 'Профиль и заказы', 'user-alt']
];
const Glyph = ({gift = false, color = '#fff'}) => <Svg width={24} height={24} viewBox="0 0 24 24">
    <Path d={gift ? 'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8H7a3 3 0 1 1 3-3l2 3zm0 0h5a3 3 0 1 0-3-3l-2 3z'
        : 'M3 7h11v9H3zM14 10h4l3 3v3h-7zM6 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM18 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z'}
        fill="none" stroke={color} strokeWidth={1.7} strokeLinecap="round" strokeLinejoin="round"/>
</Svg>;

const RingButton = ({calculation, gift, progress = 0, label, onPress}) => {
    const color = THEME.MAIN_COLOR;
    const segments = calculation ? ringSegments(calculation) : [{index:0, length:Math.PI*50, slot:Math.PI*50, segment:Math.PI*50, progress}];
    const animatedProgress = useSmoothValues(segments.map(s => s.progress));
    const [appearance] = useSmoothValues([1], 280, true);
    return <View pointerEvents={appearance > .9 ? 'box-none' : 'none'}
        style={{width:56*appearance, height:56, marginLeft:8*appearance, flexShrink:0}}>
        <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress}
        style={({pressed}) => [styles.round, {opacity:appearance*(pressed ? .75 : 1),
            transform:[{scale:.85+.15*appearance}, {translateY:6*(1-appearance)}]}]}>
        <Svg width={56} height={56} viewBox="0 0 56 56" style={StyleSheet.absoluteFill}>
            {segments.map((segment, index) => {
                const s = {...segment, progress:animatedProgress[index] ?? segment.progress};
                return <React.Fragment key={s.index}>
                <Circle cx={28} cy={28} r={25} fill="none" stroke={color} strokeOpacity={.2} strokeWidth={3}
                    strokeLinecap="round" strokeDasharray={[s.segment, s.length-s.segment]} strokeDashoffset={-s.index*s.slot} rotation={-90} originX={28} originY={28}/>
                {s.progress > 0 ? <Circle cx={28} cy={28} r={25} fill="none" stroke={color} strokeWidth={3} strokeLinecap="round"
                    strokeDasharray={[s.segment*s.progress, s.length-s.segment*s.progress]} strokeDashoffset={-s.index*s.slot} rotation={-90} originX={28} originY={28}/> : null}
            </React.Fragment>;})}
        </Svg>
        <View style={[styles.roundInside, {backgroundColor:color}]}><Glyph gift={gift} color={BUTTONTHEME.COLOR_TEXT || '#fff'}/></View>
    </Pressable></View>;
};

function DockEntrance({children, style}) {
    const [visibility] = useSmoothValues([1], 240, true);
    return <View pointerEvents="box-none" style={[style, {opacity:visibility,
        transform:[{translateY:(1-visibility)*8}]}]}>{children}</View>;
}

function RisingSheet({children, style}) {
    const {height} = useWindowDimensions();
    const [shown] = useSmoothValues([1], 320, true);
    return <Pressable accessibilityViewIsModal onPress={() => {}}
        style={[style, {transform:[{translateY:(1-shown)*height}]}]}>
        {children}
    </Pressable>;
}

function OrderButton({children, style, ...props}) {
    const [shown] = useSmoothValues([1], 280, true);
    return <Pressable {...props} style={state => [
        typeof style === 'function' ? style(state) : style,
        {opacity:shown*(state.pressed ? .85 : 1), transform:[{translateY:6*(1-shown)}]}
    ]}>{children}</Pressable>;
}



function useKeyboardVisible() {
    const [visible, setVisible] = useState(false);
    useEffect(() => {
        if (Platform.OS !== 'web') {
            const show = Keyboard.addListener('keyboardDidShow', () => setVisible(true));
            const hide = Keyboard.addListener('keyboardDidHide', () => setVisible(false));
            return () => {show.remove(); hide.remove();};
        }
        const update = () => {
            const el = document.activeElement;
            setVisible(!!el && (['INPUT','TEXTAREA','SELECT'].includes(el.tagName) || el.isContentEditable));
        };
        document.addEventListener('focusin', update);
        let timer;
        const blur = () => {clearTimeout(timer); timer = setTimeout(update, 0);};
        document.addEventListener('focusout', blur);
        return () => {clearTimeout(timer); document.removeEventListener('focusin', update); document.removeEventListener('focusout', blur);};
    }, []);
    return visible;
}

export function FloatingDock({state, navigation}) {
    const dispatch = useDispatch();
    const basket = useSelector(s => s.post.basket);
    const toppings = useSelector(s => s.post.basketTopping);
    const gifts = useSelector(s => s.post.giftsList);
    const promo = useSelector(s => s.post.promokodeActive);
    const three = useSelector(s => s.post.ThreeForTwoActive);
    const threeSettings = useSelector(s => s.post.TreeForTwoList);
    const address = useSelector(s => s.post.adressSelect);
    const delivery = useSelector(s => s.post.typeDeliverySystem);
    const points = useSelector(s => s.post.allPointsSale);
    const pointsAffect = useSelector(s => s.post.bonusPointsAffectDelivery);
    const modals = useSelector(s => s.post.modalStateStatus);
    const sum = GetAllPriceBasket();
    const count = countBasket(basket, toppings);
    const calculation = calculateDelivery(address?.diliveryData, sum, points, pointsAffect);
    const gift = giftProgress(gifts, sum);
    const giftAllowed = gift && !(three && threeSettings?.dopSettings?.additionGifts === false && threeSettings?.dopSettings?.priorityGift === false);
    const [menu, setMenu] = useState(false);
    const [giftInfo, setGiftInfo] = useState(false);
    const keyboard = useKeyboardVisible();
    const insets = useSafeAreaInsets();
    const {height:footerHeight} = useContext(FooterClearance);
    const {width} = useWindowDimensions();
    const [labelWidth, setLabelWidth] = useState(100);
    const [sumWidth, setSumWidth] = useState(80);
    const buttonText = BUTTONTHEME.COLOR_TEXT || '#fff';
    const active = state.routes[state.index];
    const catalog = active.name === 'Catalog' && (getFocusedRouteNameFromRoute(active) || 'Main') === 'Main';
    const ringCount = Number(delivery === true && calculation.dynamic) + Number(!!giftAllowed);
    // 24 — края, 44+8 — меню с промежутком, 32 — внутренние отступы заказа.
    const requiredWidth = 24 + 44 + 8 + 32 + (width < 350 ? 19 : labelWidth) + 8 + sumWidth + ringCount*64;
    const inlineMenu = catalog && count > 0 && width >= requiredWidth;
    const mobileSplit = !inlineMenu && ringCount > 0;
    const [menuBottom] = useSmoothValues([catalog && count > 0 && !inlineMenu ? 66 : 6], 280);
    const modalOpen = Object.values(modals || {}).some(value => value === true);
    const bottom = Math.max(0, Number(insets.bottom) || 0);
    const hidden = keyboard || modalOpen;
    useEffect(() => {setMenu(false); setGiftInfo(false);}, [active.key, catalog]);
    const go = name => {
        setMenu(false);
        const route = state.routes.find(item => item.name === name);
        if (!route) return;
        const event = navigation.emit({type:'tabPress', target:route.key, canPreventDefault:true});
        if (!event.defaultPrevented) navigation.navigate(name, name === 'Catalog' ? {screen:'Main'} : undefined);
    };
    return <>
        {/* Измеряем надпись до первого заказа, а не после появления панели. */}
        <View pointerEvents="none" accessibilityElementsHidden importantForAccessibility="no-hide-descendants"
            style={{position:'absolute',width:1000,height:0,overflow:'hidden',opacity:0}}>
            <Text onLayout={event => setLabelWidth(Math.ceil(event.nativeEvent.layout.width))}
                style={[styles.pillLabel,{alignSelf:'flex-start'}]}>Мой заказ</Text>
            <Text onLayout={event => setSumWidth(Math.ceil(event.nativeEvent.layout.width))}
                style={[styles.pillSum,{alignSelf:'flex-start',marginLeft:0}]}>{money(sum)}</Text>
        </View>
        {!hidden ? <DockEntrance style={[styles.position, {bottom:!catalog && footerHeight > 0 ? footerHeight+10 : 10+bottom}]}>
            <View pointerEvents="box-none" style={[styles.row, catalog ? styles.catalogRow : styles.screenMenuRow]}>
                <Pressable accessibilityRole="button" accessibilityLabel="Открыть разделы приложения" onPress={() => setMenu(true)}
                    style={({pressed}) => [styles.menuButton, styles.shadow,
                        styles.catalogMenu, {bottom:menuBottom},
                        {opacity:pressed ? .75 : 1}]}>
                    <View style={styles.menuLine}/><View style={styles.menuLine}/><View style={styles.menuLine}/>
                </Pressable>
                {inlineMenu ? <View pointerEvents="none" style={{width:52,flexShrink:0}}/> : null}
                {catalog && count > 0 ? <>
                    <OrderButton accessibilityRole="button" accessibilityLabel={count ? 'Корзина, '+count+' товаров, '+money(sum) : 'Открыть пустую корзину'}
                        onPress={() => go('Basket')} style={({pressed}) => [styles.pill, styles.shadow,
                            mobileSplit ? {marginLeft:0,marginRight:'auto'} : null,
                            {backgroundColor:THEME.MAIN_COLOR, opacity:pressed ? .85 : 1}]}>
                        {count && width < 350 ? <NavigationIcon name="shopping-bag" size={19} color={buttonText}/> :
                            <Text numberOfLines={1}
                                style={[styles.pillLabel, {color:buttonText}]}>{count ? 'Мой заказ' : 'Корзина'}</Text>}
                        {count ? <Text numberOfLines={1}
                            style={[styles.pillSum, {color:buttonText}]}>{money(sum)}</Text> : null}
                    </OrderButton>
                    {delivery === true && calculation.dynamic ? <DynamicDeliveryInfo calculation={calculation}
                        renderTrigger={open => <RingButton calculation={calculation} onPress={open} label={'Условия доставки, сейчас '+money(calculation.price)}/>}/> : null}
                    {giftAllowed ? <RingButton gift progress={gift.progress} label={gift.ready ? 'Выбрать подарок' : 'Подарки к заказу'}
                        onPress={() => setGiftInfo(true)}/> : null}
                </> : null}
            </View>
        </DockEntrance> : null}
        {menu ? <Modal transparent visible animationType="fade" onRequestClose={() => setMenu(false)}>
            <Pressable style={styles.overlay} onPress={() => setMenu(false)}>
                <RisingSheet style={[styles.sheet, {paddingBottom:16+bottom}]}>
                    <View style={styles.sheetHeading}><Text style={styles.sheetTitle}>Разделы</Text>
                        <Pressable accessibilityLabel="Закрыть меню" onPress={() => setMenu(false)} hitSlop={12}><Text style={styles.close}>×</Text></Pressable></View>
                    <ScrollView>{sections.map(([name, label, icon]) => <Pressable key={name} accessibilityRole="button" accessibilityState={{selected:active.name === name}}
                        onPress={() => go(name)} style={({pressed}) => [styles.section, {backgroundColor:pressed ? '#f4f4f4' : 'transparent'}]}>
                        <NavigationIcon name={icon} size={21} color={active.name === name ? THEME.MAIN_COLOR : '#444'}/>
                        <Text style={[styles.sectionText, {color:active.name === name ? THEME.MAIN_COLOR : '#252527'}]}>{label}</Text>
                        {name === 'Basket' && count > 0 ? <Text style={styles.sectionMeta}>{count} · {money(sum)}</Text> : null}
                    </Pressable>)}</ScrollView>
                </RisingSheet>
            </Pressable>
        </Modal> : null}
        {giftInfo ? <Modal transparent visible animationType="fade" onRequestClose={() => setGiftInfo(false)}>
            <Pressable style={styles.overlay} onPress={() => setGiftInfo(false)}>
                <RisingSheet style={[styles.sheet, {paddingBottom:16+bottom}]}>
                    <View style={styles.sheetHeading}><Text style={styles.sheetTitle}>Подарок к заказу</Text>
                        <Pressable accessibilityLabel="Закрыть подарки" onPress={() => setGiftInfo(false)} hitSlop={12}><Text style={styles.close}>×</Text></Pressable></View>
                    <ScrollView>{giftAllowed ? <GiftContents gifts={gifts} sum={sum} blocked={!!promo}/>
                        : <Text>Сейчас подарки недоступны.</Text>}</ScrollView>
                </RisingSheet>
            </Pressable>
        </Modal> : null}
        {gifts?.ready && gifts?.OneGift && modals?.MODAL_GIFTS ? <GiftVariantModal/> : null}
    </>;
}
