import {ServerDB} from '../serverDb';

export function menuStopContextKey(cityId, preorder, delivery, affiliate) {
    return JSON.stringify([String(cityId), String(preorder?.dateDelivery || 0),
        String(preorder?.timeDelivery || 0), !!delivery,
        delivery ? '' : String(affiliate?.idAffiliate ?? affiliate?.id ?? affiliate ?? 0)]);
}

export async function refreshMenuStopCatalog(cityId, dispatch) {
    const startedAt = Date.now();
    try {
        const result = await ServerDB.getCatalogProducts(cityId);
        if (result?.list && !result.error) {
            dispatch({type:'MENU_STOP_REFRESH', cityId, catalog:result.list, startedAt});
        }
    } catch (_) {
        // При плохой связи сохраняем корзину и отметки из ответа сервера.
    }
}

export function applyMenuStopOrderFeedback(result, context, dispatch) {
    if (result?.errorCode !== 'PRODUCT_BLOCKED_MENU_STOP' || result.menuStopTestRejection) return;
    const products = Array.isArray(result.blockedProducts) ? result.blockedProducts : [];
    if (!products.length) return;
    dispatch({type:'MENU_STOP_ORDER_REJECTED', cityId:context.cityId,
        contextKey:menuStopContextKey(context.cityId, context.preorder, context.delivery, context.affiliate),
        products, receivedAt:Date.now()});
    // Не задерживаем показ уведомления ожиданием каталога.
    void refreshMenuStopCatalog(context.cityId, dispatch);
}
