const toMoney = (value) => {
    const number = Number(value);
    return Number.isFinite(number) ? Math.max(0, Math.round(number)) : 0;
};

export const normalizeDeliveryRanges = (rawRanges) => {
    let ranges = rawRanges;
    if (typeof ranges === 'string') {
        try {
            ranges = JSON.parse(ranges);
        } catch (e) {
            return [];
        }
    }
    if (!Array.isArray(ranges) || ranges.length === 0) {
        return [];
    }

    const normalized = [];
    for (let index = 0; index < ranges.length; index += 1) {
        const source = ranges[index] || {};
        const from = Number(source.from);
        const price = Number(source.price);
        const isLast = index === ranges.length - 1;
        const to = source.to === null || source.to === '' ? null : Number(source.to);

        if (!Number.isInteger(from) || from < 0 || !Number.isInteger(price) || price < 0) {
            return [];
        }
        if ((!isLast && (!Number.isInteger(to) || to < from)) || (isLast && to !== null)) {
            return [];
        }
        if ((index === 0 && from !== 0) || (index > 0 && from !== normalized[index - 1].to + 1)) {
            return [];
        }

        normalized.push({
            from,
            to,
            price,
            api_id: typeof source.api_id === 'string' ? source.api_id.trim() : ''
        });
    }
    return normalized;
};

export const calculateDelivery = (deliveryData, productsSum, pointsSale = 0, bonusPointsAffectDelivery = false) => {
    const source = deliveryData || {};
    const baseProductsSum = toMoney(productsSum);
    const calculationSum = bonusPointsAffectDelivery
        ? Math.max(0, baseProductsSum - toMoney(pointsSale))
        : baseProductsSum;
    const ranges = normalizeDeliveryRanges(source.delivery_price_ranges);

    if (ranges.length > 0) {
        let currentIndex = ranges.findIndex((range) => calculationSum >= range.from && (range.to === null || calculationSum <= range.to));
        if (currentIndex < 0) {
            currentIndex = ranges.length - 1;
        }
        const currentRange = ranges[currentIndex];
        const nextRange = ranges[currentIndex + 1] || null;
        const freeRange = ranges.slice(currentIndex).find((range) => range.price === 0) || null;

        return {
            dynamic: true,
            price: currentRange.price,
            calculationSum,
            ranges,
            currentIndex,
            currentRange,
            nextRange,
            amountToNext: nextRange ? Math.max(0, nextRange.from - calculationSum) : 0,
            amountToFree: freeRange ? Math.max(0, freeRange.from - calculationSum) : null,
            apiId: currentRange.api_id || source.api_id || ''
        };
    }

    const legacyPrice = toMoney(source.priceDilivery);
    const freeFrom = toMoney(source.min_sum_free_dilivery);
    const isFree = calculationSum >= freeFrom;
    return {
        dynamic: false,
        price: isFree ? 0 : legacyPrice,
        calculationSum,
        ranges: [],
        currentIndex: 0,
        currentRange: null,
        nextRange: null,
        amountToNext: isFree ? 0 : Math.max(0, freeFrom - calculationSum),
        amountToFree: isFree ? 0 : Math.max(0, freeFrom - calculationSum),
        apiId: source.api_id || ''
    };
};

export const estimateBasketSum = (basket, catalog, basketTopping = [], toppingCatalog = []) => {
    let sum = 0;
    (Array.isArray(basket) ? basket : []).forEach((basketProduct) => {
        (Array.isArray(basketProduct?.type) ? basketProduct.type : []).forEach((basketType) => {
            const variants = catalog?.[basketType.categoryId]?.ProductList?.[basketProduct.id];
            const product = Array.isArray(variants)
                ? variants.find((variant) => String(variant?.type_product) === String(basketType?.type_id))
                : null;
            if (!product) {
                return;
            }
            const discountPrice = product.price_discount && product.price_discount !== false
                ? Number(product.price_discount.new_price)
                : Number(product.price);
            const modifyPrice = (Array.isArray(basketType.modifyList) ? basketType.modifyList : [])
                .reduce((result, item) => result + (Number(item?.price) || 0), 0);
            sum += Math.max(0, (discountPrice || 0) + modifyPrice) * Math.max(0, Number(basketType.count) || 0);
        });
    });
    (Array.isArray(basketTopping) ? basketTopping : []).forEach((basketItem) => {
        const topping = (Array.isArray(toppingCatalog) ? toppingCatalog : []).find((item) => String(item?.id) === String(basketItem?.id));
        if (topping) {
            sum += Math.max(0, Number(topping.price) || 0) * Math.max(0, Number(basketItem.count) || 0);
        }
    });
    return Math.round(sum);
};
