import * as Font from 'expo-font';
import {AntDesign, Entypo, Feather, FontAwesome, FontAwesome5, Ionicons, MaterialCommunityIcons, MaterialIcons} from '@expo/vector-icons';

const fonts = {
    ...AntDesign.font, ...Entypo.font, ...Feather.font, ...FontAwesome.font,
    ...FontAwesome5.font, ...Ionicons.font, ...MaterialCommunityIcons.font, ...MaterialIcons.font
};

const listeners = new Set();
export function subscribeIconFonts(listener) {
    listeners.add(listener);
    return () => listeners.delete(listener);
}
function notifyLoaded() {
    listeners.forEach(listener => listener());
}

function withTimeout(promise, milliseconds) {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => reject(new Error('Icon font timeout')), milliseconds);
        promise.then(value => { clearTimeout(timer); resolve(value); }, error => { clearTimeout(timer); reject(error); });
    });
}

export async function loadIconFonts() {
    // Каждое семейство повторяется независимо; уже загруженные не скачиваются снова.
    const results = await Promise.all(Object.entries(fonts).map(async ([name, source]) => {
        for (let attempt = 0; attempt < 3; attempt++) {
            if (Font.isLoaded(name)) { notifyLoaded(); return true; }
            try {
                await withTimeout(Font.loadAsync(name, source).then(() => notifyLoaded()), 12000);
                if (Font.isLoaded(name)) return true;
            } catch (error) {
                // Expo объединяет параллельные загрузки одного семейства.
            }
            if (attempt < 2) await new Promise(resolve => setTimeout(resolve, 3000 * (attempt + 1)));
        }
        return Font.isLoaded(name);
    }));
    if (results.some(loaded => !loaded)) throw new Error('Icon fonts unavailable');
}
