// Города верхнего уровня (city_bind), не вложенные населённые пункты listCity.
export function parseCityDirectory(raw) {
    const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (!data || data.error || data.typeData !== 'CityUser' || !data.list || typeof data.list !== 'object') {
        throw new Error('Не удалось получить список городов');
    }
    const cities = {};
    Object.values(data.list).forEach(row => {
        if (!row || !/^\d+$/.test(String(row.id)) || Number(row.id) <= 0 || !String(row.title || '').trim()) {
            throw new Error('Некорректный список городов');
        }
        cities[String(row.id)] = String(row.title).trim();
    });
    const phones = {};
    Object.keys(cities).forEach(id => {
        const phone = data.phoneNumberCityPoint?.[id];
        if (phone && typeof phone.tel === 'string' && /^\+?\d{5,15}$/.test(phone.tel)) {
            phones[id] = {tel: phone.tel, telTile: String(phone.telTile || phone.tel)};
        }
    });
    return {data, cities, phones};
}

export function resolveDirectoryCity(cities, stored, candidate) {
    const previous = stored?.cityId ? stored : candidate;
    const id = String(previous?.cityId || previous?.idCity || '');
    if (id) {
        return cities[id] ? {cityId: id, cityName: cities[id]} : null;
    }
    const ids = Object.keys(cities);
    return ids.length === 1 ? {cityId: ids[0], cityName: cities[ids[0]]} : null;
}

// Читаем только city, не меняя параметры подписи ВК и hash навигации.
export function readCityFromSearch(search) {
    const params = new URLSearchParams(search || '');
    const values = params.getAll('city');
    if (!values.length) return {present: false, id: null};
    const value = values[0].trim();
    const valid = values.length === 1 && /^[0-9]+$/.test(value) && Number.isSafeInteger(Number(value)) && Number(value) > 0;
    return {present: true, id: valid ? String(Number(value)) : null};
}

export function resolveVkUrlCity(cities, stored, urlCity) {
    if (urlCity.present) {
        return urlCity.id && cities[urlCity.id] ? {cityId: urlCity.id, cityName: cities[urlCity.id]} : null;
    }
    return resolveDirectoryCity(cities, stored, null);
}
