import {useEffect} from 'react';
import {loadIconFonts} from '../utils/iconFonts';

// Только фоновая загрузка: ошибки и ожидание не блокируют навигацию.
export default function IconAssetsGate({children}) {
    useEffect(() => {
        loadIconFonts().catch(() => {
            // Повторы ограничены загрузчиком; без блокировки интерфейса.
        });
    }, []);
    return children;
}
