import {useEffect, useRef, useState} from 'react';
import {AccessibilityInfo, Platform} from 'react-native';

// Анимация локальна: не обновляет Redux, каталог и его позицию прокрутки.
export function useSmoothValues(target, duration = 380, enter = false) {
    const signature = JSON.stringify(target);
    const [values, setValues] = useState(() => enter ? target.map(() => 0) : target);
    const current = useRef(values);
    const [reduce, setReduce] = useState(() => Platform.OS === 'web' && typeof window !== 'undefined' && window.matchMedia
        ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : true);
    useEffect(() => {
        if (Platform.OS === 'web' && typeof window !== 'undefined' && window.matchMedia) {
            const media = window.matchMedia('(prefers-reduced-motion: reduce)');
            const update = () => setReduce(media.matches);
            update();
            if (media.addEventListener) media.addEventListener('change', update);
            else media.addListener(update);
            return () => {
                if (media.removeEventListener) media.removeEventListener('change', update);
                else media.removeListener(update);
            };
        }
        let live = true;
        AccessibilityInfo?.isReduceMotionEnabled().then(value => {if (live) setReduce(value);}).catch(() => {});
        const subscription = AccessibilityInfo?.addEventListener('reduceMotionChanged', setReduce);
        return () => {live = false; subscription?.remove();};
    }, []);
    useEffect(() => {
        const next = JSON.parse(signature);
        const from = next.map((value, index) => current.current[index] ?? value);
        if (reduce || from.every((value, index) => value === next[index])) {
            current.current = next;
            setValues(next);
            return;
        }
        let frame, start;
        const tick = now => {
            if (start === undefined) start = now;
            const t = Math.min(1, (now - start) / duration);
            const eased = 1 - Math.pow(1 - t, 3);
            current.current = next.map((value, index) => from[index] + (value - from[index]) * eased);
            setValues(current.current);
            if (t < 1) frame = requestAnimationFrame(tick);
        };
        frame = requestAnimationFrame(tick);
        return () => cancelAnimationFrame(frame);
    }, [signature, duration, reduce]);
    return values;
}
