import React, {createContext, useCallback, useContext, useEffect, useMemo, useRef, useState} from 'react';
import {useIsFocused} from '@react-navigation/native';

export const FooterClearance = createContext({height:0, setHeight:()=>{}});
const FooterWriter = createContext(()=>{});

// Измерения обновляют только панель навигации, не дерево экранов и слайдеры.
export function FooterClearanceProvider({children}) {
    const [height, setHeight] = useState(0);
    const value = useMemo(()=>({height}), [height]);
    return <FooterWriter.Provider value={setHeight}>
        <FooterClearance.Provider value={value}>{children}</FooterClearance.Provider>
    </FooterWriter.Provider>;
}

export function useFooterClearance() {
    const setHeight = useContext(FooterWriter);
    const focused = useIsFocused();
    const measured = useRef(0);
    useEffect(() => {
        if (!focused) return;
        setHeight(measured.current);
        return () => setHeight(0);
    }, [focused, setHeight]);
    return useCallback(event => {
        const height = Math.ceil(event.nativeEvent.layout.height);
        if (!Number.isFinite(height) || height <= 0 || measured.current === height) return;
        measured.current = height;
        if (focused) setHeight(height);
    }, [focused, setHeight]);
}
