import React, {useEffect, useState} from 'react';
import {View, Text, StyleSheet} from 'react-native';
import {getConnectionStatus, subscribeConnectionStatus} from '../utils/connectionStatus';

export default function ConnectionBanner() {
    const [visible, setVisible] = useState(getConnectionStatus);
    useEffect(() => {
        const unsubscribe = subscribeConnectionStatus(setVisible);
        setVisible(getConnectionStatus());
        return unsubscribe;
    }, []);
    if (!visible) return null;
    return <View pointerEvents="none" style={styles.wrap}>
        <View style={styles.banner}>
            <Text accessibilityRole="alert" style={styles.title}>Проблема с соединением</Text>
            <Text style={styles.text}>Сеть или сервер отвечают медленно. Попробуйте немного позже.</Text>
        </View>
    </View>;
}
const styles = StyleSheet.create({
    wrap:{position:'absolute',top:8,left:12,right:12,zIndex:10000,alignItems:'center'},
    banner:{width:'100%',maxWidth:460,backgroundColor:'#fff3d9',borderRadius:10,paddingHorizontal:14,paddingVertical:9},
    title:{fontSize:13,lineHeight:18,fontWeight:'600',color:'#664b15'},
    text:{fontSize:12,lineHeight:16,color:'#745d30'}
});
