import React, { useState, useRef, useEffect } from 'react';
import {
    View,
    Text,
    StyleSheet,
    TextInput,
    Image,
    Pressable,
    Platform,
    SafeAreaView,
    ActivityIndicator,
    Linking
} from 'react-native';
import {ServerDB} from '../serverDb';
import {useDispatch, useSelector} from 'react-redux';
import { HeaderButtons, Item } from 'react-navigation-header-buttons';
import { AppHeaderIcon } from '../components/AppHeaderIcon';
import { THEME } from '../theme';
import '../styleForm.css';
import {
    setCityUserSystemPhone,
    valinPhoneNumberRu,
    setPhoneNumberDataBase,
    setTimeSendSms,
    setStatusAuthScreen,
    loadAuthInfo
} from '../store/actions/post';
import {ActiveSiteSettings} from "../activeSiteSettings";
import bridge from '@vkontakte/vk-bridge';
import axios from 'axios';


export const AuthorizationScreen = ({ navigation, route }) => {
    const statusLoadingAuthScreen = useSelector(state=>state.post.statusLoadingAuthScreen);
    const AuthTG = useSelector(state => state.post.authTg);


    const padTime = time => {
        return String(time).length === 1 ? `0${time}` : `${time}`;
    };

    const format = time => {
        const minutes = Math.floor(time / 60);
        const seconds = time % 60;
        return `${minutes}:${padTime(seconds)}`;
    };
    const reloadSendSmsTime = 30;

    const [counter, setCounter] = useState(0);
    const [loading, setLoading] = useState(false); // Состояние для прелоадера
    const [loadingVK, setLoadingVK] = useState(false); // Состояние для прелоадера
    useEffect(() => {
        let timer;
        if (counter > 0) {
            timer = setTimeout(() => setCounter(c => c - 1), 1000);
        }

        return () => {
            if (timer) {
                clearTimeout(timer);
            }
        };
    }, [counter]);

    const dispatch = useDispatch();
    const [text, setText] = useState('');

    const PhoneDefault = useSelector(state => state.post.phoneNumberKeyboard);
    const idUserVk = useSelector(state => state.post.idUserVK);

    const [phoneNumberState, setphoneNumberState] = useState(PhoneDefault);
    const [pincodeNumber, setPincodeNumber] = useState(null);
    const loadPageDefault = useSelector(state => state.post.loadPageDefault);

    const [validPhoneNumberStatus, setStstusValinPhoneNumber] = useState(false);
    const [validPincodeStatus, setStatusValinPincode] = useState(true);
    const [validPincodeStatusGreen, setPincodeStatusGreen] = useState(false);
    const [authStep, setAuthStep] = useState('method'); // method | code | reverse_call
    const [callAuthMethod, setCallAuthMethod] = useState('call_code');
    const [authMethods, setAuthMethods] = useState({
        greensms_call: true,
        telegram: false,
        vk: true,
        max: false
    });
    const [reverseCallPhoneTo, setReverseCallPhoneTo] = useState('');
    const [activeBotLink, setActiveBotLink] = useState({
        title: 'Telegram',
        url: 'https://t.me/auth_pixelcrm_bot?start=1'
    });
    const reverseCallPollRef = useRef(null);
    const imgRef = useRef();

    const CityLoadPhone =  useSelector(state => state.post.cityLoadPhone);
    const AuthUserStatus =  useSelector(state => state.post.AuthUserStatus);

    const saveHandler = async (cityId,cityName) => {
        const post = {
            cityId,
            cityName
        };
        await dispatch(setCityUserSystemPhone(post));
        window.location.hash = 'Catalog';
        navigation.navigate('Catalog');
    };

    const validnumberNull = (number = null)=>{
        switch (number) {
            case null: return '+7';
            case '+': return '+7';
            default: return number;
        }
    };

    const checkNumber = (number) => {
        const valinNumber = valinPhoneNumberRu(number);
        setStstusValinPhoneNumber(valinNumber);
        setphoneNumberState(valinNumber);
        dispatch(setPhoneNumberDataBase(validnumberNull(number)));
    };

    const checkPincode = (number) => {
        setPincodeNumber(number);
        if(number.length>3){
            getStatusCodeServer(number);
        }
    };

    const setSuccessAuthStatus = async ()=>{
        await setStatusValinPincode(true);
        setPincodeStatusGreen(true);
        await dispatch(loadAuthInfo(true,false,false,false,false,idUserVk));
        setPincodeNumber(null);
        setStstusValinPhoneNumber(null);
        setTimeout(()=>{
            setPincodeStatusGreen(false);
            setAuthStep('method');
            setReverseCallPhoneTo('');
            dispatch(setPhoneNumberDataBase('+7'));
        },10000);
    };

    const getStatusCodeServer = async (number)=>{
            let resultCheckPinkode = await ServerDB.VerificationCodeServerCall(
                PhoneDefault,
                number,
                idUserVk?.id || null,
                CityDatas?.cityId || null
            );
            const result = resultCheckPinkode?.status?.result || resultCheckPinkode?.result || null;

            if (result === "ERROR_CODE") {
                setStatusValinPincode(false);
                    setTimeout(()=>{
                        setStatusValinPincode(true);
                        setPincodeNumber(null);
                        },500);
            } else if (result === "OK_CODE_V") {
                await setSuccessAuthStatus();
            } else {
                setStatusValinPincode(false);
                setTimeout(()=>{
                    setStatusValinPincode(true);
                },500);
            }
    };

    const parseCallAuthMethod = (response) => {
        const method = response?.auth_method || response?.status?.auth_method || response?.data?.auth_method || 'call_code';
        return method === 'reverse_call' ? 'reverse_call' : 'call_code';
    };

    const parseAuthMethods = (response) => {
        const methods = response?.auth_methods || response?.status?.auth_methods || response?.data?.auth_methods || {};
        return {
            greensms_call: methods?.greensms_call !== false,
            telegram: methods?.telegram === true,
            vk: methods?.vk !== false,
            max: methods?.max === true
        };
    };

    const loadCallAuthMethod = async () => {
        try{
            const response = await ServerDB.VerificationAuthMethods(CityDatas?.cityId || null);
            console.log('[Auth] VerificationAuthMethods response:', response);
            if(!response?.auth_methods && !response?.status?.auth_methods && !response?.data?.auth_methods){
                throw new Error('VerificationAuthMethods unavailable');
            }
            setCallAuthMethod(parseCallAuthMethod(response));
            setAuthMethods(parseAuthMethods(response));
        }catch (e){
            console.log('[Auth] VerificationAuthMethods error:', e);
            try{
                const response = await ServerDB.VerificationCallAuthMethod(CityDatas?.cityId || null);
                console.log('[Auth] VerificationCallAuthMethod response:', response);
                setCallAuthMethod(parseCallAuthMethod(response));
            }catch (fallbackError){
                console.log('[Auth] VerificationCallAuthMethod error:', fallbackError);
                setCallAuthMethod('call_code');
            }
        }
    };

    const clearReverseCallPoll = () => {
        if(reverseCallPollRef.current){
            clearInterval(reverseCallPollRef.current);
            reverseCallPollRef.current = null;
        }
    };

    const checkReverseCallStatus = async () => {
        try{
            const response = await ServerDB.VerificationCodeServerReverseCall(
                PhoneDefault,
                idUserVk?.id || null,
                CityDatas?.cityId || null
            );
            console.log('[Auth] VerificationCodeServerReverseCall response:', response);
            const result = response?.status?.result || response?.result || null;
            if(result === 'OK_CODE_V'){
                clearReverseCallPoll();
                await setSuccessAuthStatus();
                return;
            }
            if(result === 'ERROR_CODE'){
                clearReverseCallPoll();
                alert(response?.status?.ERROR_MSG || 'Не удалось подтвердить звонок. Попробуйте снова.');
            }
        }catch (e){
            console.log('[Auth] VerificationCodeServerReverseCall error:', e);
        }
    };

    const startCodeCallFlow = async () => {
        setAuthStep('code');
        dispatch(setTimeSendSms(new Date().getMilliseconds()+(30*1000)));
        setCounter(reloadSendSmsTime);
        await ServerDB.VerificationPhoneServerCall(PhoneDefault, CityDatas?.cityId || null);
    };

    const startReverseCallFlow = async () => {
        try{
            const response = await ServerDB.VerificationPhoneServerReverseCall(PhoneDefault, CityDatas?.cityId || null);
            console.log('[Auth] VerificationPhoneServerReverseCall response:', response);
            const result = response?.status?.result || response?.result || null;
            if(result === 'OK_SMS'){
                const phoneTo = response?.status?.data?.phoneTo || response?.data?.phoneTo || null;
                if(!phoneTo){
                    alert('Не удалось получить номер для звонка.');
                    return;
                }
                setReverseCallPhoneTo(phoneTo);
                setAuthStep('reverse_call');
                clearReverseCallPoll();
                reverseCallPollRef.current = setInterval(checkReverseCallStatus, 5000);
                return;
            }
            if(result === 'ERROR_LIMIT'){
                alert(response?.status?.ERROR_MSG || 'Превышен лимит запросов, попробуйте позже.');
                return;
            }
            if(result === 'ERROR_SMS_CONFIG' || result === 'ERROR_SMS_SEND'){
                alert('Сервис обратного звонка недоступен, переключаем на код в звонке.');
                setCallAuthMethod('call_code');
                await startCodeCallFlow();
                return;
            }
            alert('Не удалось запустить обратный звонок.');
        }catch (e){
            alert('Ошибка запуска обратного звонка.');
        }
    };

    const startCallAuthFlow = async () => {
        if(!validPhoneNumberStatus){ return; }
        if(callAuthMethod === 'reverse_call'){
            await startReverseCallFlow();
            return;
        }
        await startCodeCallFlow();
    };

    const normalizePhoneForDisplay = (value) => {
        const digits = String(value || '').replace(/\D/g, '');
        if(digits.length === 10){
            return `7${digits}`;
        }
        if(digits.length === 11){
            if(digits[0] === '8'){
                return `7${digits.slice(1)}`;
            }
            return digits;
        }
        return digits;
    };

    const formatPhoneForDisplay = (value) => {
        const digits = normalizePhoneForDisplay(value);
        if(digits.length !== 11){
            return value || '';
        }
        return `+${digits[0]} ${digits.slice(1,4)} ${digits.slice(4,7)}-${digits.slice(7,9)}-${digits.slice(9,11)}`;
    };

    const getPhoneTelLink = (value) => {
        const digits = normalizePhoneForDisplay(value);
        return digits.length === 11 ? `tel:+${digits}` : `tel:${String(value || '').trim()}`;
    };

    const handlePhoneDial = (event, value) => {
        if(event && typeof event.preventDefault === 'function'){
            event.preventDefault();
        }
        const telLink = getPhoneTelLink(value);
        try{
            if(window.ReactNativeWebView && window.ReactNativeWebView.postMessage){
                window.ReactNativeWebView.postMessage(JSON.stringify({
                    task: 'openLink',
                    url: telLink
                }));
            }
        }catch (e){}
        try{
            window.location.href = telLink;
        }catch (e){}
    };

    const sendPhoneToBot = async (phone, siteUrl, type = 'tg') => {
    console.log(phone, siteUrl);
    let linkBot = '/moduls/AuthTG/obr/setCookieBot.php?setTokenBotTg=1&defouldData=1';
    switch (type) {
        case "tg": linkBot = '/moduls/AuthTG/obr/setCookieBot.php?setTokenBotTg=1'; break;
        case "vk": linkBot = '/moduls/AuthTG/obr/setCookieBot.php?setTokenBotVK=1'; break;
        case "max": linkBot = '/moduls/AuthTG/obr/setCookieBot.php?setTokenBotMax=1'; break;
        default:linkBot = '/moduls/AuthTG/obr/setCookieBot.php?setTokenBotTg=1&defouldData=2';
    }

        try {
            const response = await fetch(siteUrl+linkBot, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
            body: `phone=${encodeURIComponent(phone)}&site_url=${encodeURIComponent(siteUrl)}&idVkUser=${encodeURIComponent(idUserVk.id)}`
            });

        const text = await response.text();
        console.log('Response from server:', text); // Логирование полного ответа от сервера

        const data = JSON.parse(text); // Преобразование текста в JSON
            return data;
        } catch (error) {
            console.error('Ошибка при отправке данных на сервер с ботом:', error);
            return { success: false, message: 'Ошибка при отправке данных на сервер с ботом' };
        }
    };

    const generateTokenAndAuth = async () => {
        const telegramBotLink = 'https://t.me/auth_pixelcrm_bot?start=1';
        setActiveBotLink({title: 'Telegram', url: telegramBotLink});
        setLoading(true); // Устанавливаем состояние загрузки
        const phone = PhoneDefault;
        const siteUrl = ActiveSiteSettings.URL; // Используем URL API
        if (phone) {
            const data = await sendPhoneToBot(phone, siteUrl, 'tg');
            if (data.success) {
                // Открываем ссылку в новой вкладке
                Linking.openURL(telegramBotLink);
                checkAuthStatus(data.token,siteUrl); // Запускаем проверку авторизации
            } else {
                setLoading(false); // Отключаем прелоадер в случае ошибки
                alert('Ошибка: ' + data.message);
            }
        } else {
            setLoading(false); // Отключаем прелоадер в случае ошибки
            alert('Пожалуйста, введите ваш номер телефона.');
        }
    };

    const generateTokenAndAuthVK = async () => {
        setLoading(true); // Устанавливаем состояние загрузки
        setLoadingVK(true); // Устанавливаем состояние загрузки
        bridge
            .send('VKWebAppGetPhoneNumber')
            .then(async (data) => {
                if (data.phone_number) {
                    const phone = data.phone_number;
                    const siteUrl = ActiveSiteSettings.URL; // Используем URL API
                    if (phone) {
                        const data = await sendPhoneToBot(phone, siteUrl, 'vk');
                        if (data.success) {
                            // Открываем ссылку в новой вкладке
                            axios
                                .post('https://tghook.ebee.me/vk_webhook.php', {
                                    updateMessageVKBot:{
                                        phone_number: phone,
                                        idUserVK: idUserVk.id
                                    }
                                })
                                .then((response) => {
                                    switch (response.data?.error) {
                                        case true:
                                            setLoading(false); // Отключаем прелоадер в случае ошибки
                                            console.log('Ошибка:', response.data);
                                            break;
                                        case false:
                                            console.log('Нет ошибок:', response.data);
                                            break;
                                        default:
                                            setLoading(false); // Отключаем прелоадер в случае ошибки
                                            console.log('Ошибка есть:', response.data);
                                    }

                                })
                                .catch((error) => {
                                    setLoading(false); // Отключаем прелоадер в случае ошибки
                                    console.error('Error confirming phone:', error)
                                });

                            checkAuthStatus(data.token,siteUrl); // Запускаем проверку авторизации
                        } else {
                            setLoading(false); // Отключаем прелоадер в случае ошибки
                            alert('Ошибка: ' + data.message);
                        }
                    } else {
                        setLoading(false); // Отключаем прелоадер в случае ошибки
                        alert('Пожалуйста, введите ваш номер телефона.');
                    }

                } else {
                    // Пользователь отклонил доступ

                }
            })
            .catch((error) => {
                // Пользователь отклонил доступ
                console.error('Error requesting phone number:', error)
            });
    };

    const generateTokenAndAuthMax = async () => {
        const maxBotLink = 'https://max.ru/id312337744950_bot';
        setActiveBotLink({title: 'MAX', url: maxBotLink});
        setLoading(true);
        const phone = PhoneDefault;
        const siteUrl = ActiveSiteSettings.URL;
        if (phone) {
            const data = await sendPhoneToBot(phone, siteUrl, 'max');
            if (data.success) {
                Linking.openURL(maxBotLink);
                checkAuthStatus(data.token,siteUrl);
            } else {
                setLoading(false);
                alert('Ошибка: ' + data.message);
            }
        } else {
            setLoading(false);
            alert('Пожалуйста, введите ваш номер телефона.');
        }
    };

    const checkAuthStatus = (token,siteUrl,timeL = 5000) => {
        const interval = setInterval(async () => {
            const response = await fetch(siteUrl + '/moduls/AuthTG/obr/check_auth_status.php', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: `token=${encodeURIComponent(token)}`
            });

            const data = await response.json();
            if (data.status === 'authorized') {
                clearInterval(interval); // Останавливаем интервал
                await dispatch(loadAuthInfo(true, false, false, false, false, idUserVk)); // Загружаем данные авторизации
                setLoading(false); // Отключаем прелоадер
            }
        }, timeL); // Проверяем статус каждые 5 секунд
    };

    const CityList = useSelector(state => state.post.cityList);
    const CityDatas = useSelector(state => state.post.cityData);

    useEffect(()=> {
        loadCallAuthMethod();
        setTimeout(()=>{
            dispatch(setStatusAuthScreen(false));
        },3000);

        if(AuthUserStatus === true){
            window.location.hash = 'Catalog';
            navigation.navigate('Catalog');
        }

        return () => {
            clearReverseCallPoll();
        };
    },[dispatch,AuthUserStatus,CityDatas?.cityId]);

    if(statusLoadingAuthScreen){
        return (
            <SafeAreaView style={[styles.centeredViewWindowTop,{flex:1,alignItems:"center",justifyContent:"center"}]}>
                <ActivityIndicator color={THEME.TEXT_COLOR}  size={120} />
            </SafeAreaView>
        );
    }

    if(!AuthUserStatus){
        if(!loadPageDefault){
            return (
                  <SafeAreaView style={[styles.centeredViewWindowTop,{flex:1,alignItems:"center",justifyContent:"center",paddingBottom:"15%"}]}>
                    <>
                        <ActivityIndicator color="#FFFFFF" size="35%" style={{marginBottom:0,paddingBottom:0}}/>
                        <Text style={{color:'#FFFFFF',fontSize:18,textAlign:"center",paddingTop:0,marginTop:0}}>{"Обновление авторизационных \nданных"}</Text>
                    </>
                  </SafeAreaView>
            );
        }

        if(authStep === 'method') {
            return (
                <SafeAreaView style={styles.centeredViewWindowTop}>
                    <View style={styles.modalView}>
                        <div className="verification-title">Введите номер телефона</div>
                        <TextInput
                            style={validPhoneNumberStatus ? [styles.phoneInput, styles.phoneInputSuccess] : [styles.phoneInput,styles.phoneInputError]}
                            onChangeText={(text) => checkNumber(text)}
                            maxLength={12}
                            value={PhoneDefault}
                            multiline={false}
                            placeholder={'+79999999999'}
                            textAlign={'center'}
                            keyboardType={Platform.OS === 'android' ? "phone-pad" : "phone-pad"}
                        />
                        {loading ? (
                            <div style={{margin:"10px auto",textAlign:"center"}}>
                            <ActivityIndicator size="large" color={THEME.MAIN_COLOR} />
                                {loadingVK ? false :
                                    <Text style={{textAlign: "center", fontSize: 12, color: "#252525"}}>Если не
                                        произошло автоматическое перенаправление, перейдите в бот {activeBotLink.title} <a target="_blank"
                                                                                                     href={activeBotLink.url}>{activeBotLink.url}</a></Text>
                                }
                            </div>
                        ) : (
                            <>
                        <div className="verification-title2">Способ подтверждения</div>
                        {authMethods.greensms_call ? <Pressable
                            style={validPhoneNumberStatus ? [styles.buttonCity, styles.buttonsSuccess] : [styles.buttonCity, styles.buttonsError]}
                            disabled={validPhoneNumberStatus ? false : true}
                            color={THEME.MAIN_COLOR}
                            onPress={startCallAuthFlow}
                        >
                            <View style={validPhoneNumberStatus ? [styles.textSuccess, styles.widthBtnClass] : [styles.textError, styles.widthBtnClass]}>
                                <div className="iconAuthScreen">
                                    <img style={styles.icon} src={ActiveSiteSettings.URL+"images/system_icons/verif/call-2.png"} alt={"call"} className="icon" />
                                </div>
                                <div className="textBTNAuth">{callAuthMethod === 'reverse_call' ? 'Позвонить' : 'Код в звонке'}</div>
                            </View>
                        </Pressable> : false}
                                {AuthTG && authMethods.telegram ? <>
                        <Pressable
                            style={validPhoneNumberStatus ? [styles.buttonCity, styles.buttonsSuccess] : [styles.buttonCity, styles.buttonsError]}
                            disabled={validPhoneNumberStatus ? false : true}
                            onPress={generateTokenAndAuth}
                        >
                            <View style={validPhoneNumberStatus ? [styles.textSuccess, styles.widthBtnClass] : [styles.textError, styles.widthBtnClass]}>
                                <div className="iconAuthScreen">
                                    <img style={styles.icon} src={ActiveSiteSettings.URL+"/images/system_icons/verif/telegram-1.png"} alt="Telegram Icon"
                                          className="icon" />
                                </div>
                                <div className="textBTNAuth">Telegram</div>
                            </View>
                        </Pressable>
                                    </>
                                    : false}

                                {authMethods.vk ? <>
                                    <Pressable
                                        style={[styles.buttonCity, styles.buttonsSuccess]}
                                        onPress={generateTokenAndAuthVK}
                                    >
                                        <View style={[styles.textSuccess, styles.widthBtnClass]}>
                                            <div className="iconAuthScreen">
                                                <img style={styles.icon} src={ActiveSiteSettings.URL+"images/system_icons/verif/vk-1.png"} alt="VK"
                                                     className="icon" />
                                            </div>
                                            <div className="textBTNAuth">Вконтакте</div>
                                        </View>
                                    </Pressable>
                                </> : false}

                                {authMethods.max ? <>
                                    <Pressable
                                        style={validPhoneNumberStatus ? [styles.buttonCity, styles.buttonsSuccess] : [styles.buttonCity, styles.buttonsError]}
                                        disabled={validPhoneNumberStatus ? false : true}
                                        onPress={generateTokenAndAuthMax}
                                    >
                                        <View style={validPhoneNumberStatus ? [styles.textSuccess, styles.widthBtnClass] : [styles.textError, styles.widthBtnClass]}>
                                            <div className="iconAuthScreen">
                                                <img style={styles.icon} src={ActiveSiteSettings.URL+"images/system_icons/verif/max-1.png"} alt="MAX"
                                                     className="icon" />
                                            </div>
                                            <div className="textBTNAuth">MAX</div>
                                        </View>
                                    </Pressable>
                                </> : false}

                            </>
                        )}
                        <Text style={styles.privacyPolicyText}>
                            Введя номер телефона и нажав "Получить код", вы соглашаетесь с{' '}
                            <Text style={styles.privacyPolicyLink} onPress={() => Linking.openURL(ActiveSiteSettings.URL+'/Privacy_policy')}>
                                политикой конфиденциальности
                            </Text>.
                        </Text>
                    </View>
                    {Platform.OS === 'ios' ?
                        <View>
                            <Pressable
                                style={[styles.buttonCity, styles.buttonsSuccess,{whiteSpace:"nowrap",textAlign:"center",margin:0}]}
                                color={THEME.MAIN_COLOR}
                                onPress={() => {
                                    window.location.hash = 'Catalog';
                                    navigation.navigate('Catalog');
                                }}
                            >
                                <Text style={{color:"#fff",textAlign:"center"}}>Вернуться в каталог</Text>
                            </Pressable>
                        </View>
                        : <View>
                            <Pressable
                                style={[styles.buttonCity, styles.buttonsSuccess,{backgroundColor:"#ffffff",whiteSpace:"nowrap",textAlign:"center",margin:0}]}
                                color={THEME.MAIN_COLOR}
                                onPress={() => {
                                    window.location.hash = 'Catalog';
                                    navigation.navigate('Catalog');
                                }}
                            >
                                <Text style={{color:THEME.MAIN_COLOR,minWidth:170,textAlign:"center"}}>Вернуться в каталог</Text>
                            </Pressable>
                        </View>}
                </SafeAreaView>
            );
        }else if(authStep === 'code'){
            return (
                <SafeAreaView style={styles.centeredViewWindowTop}>
                    <View style={styles.modalView}>
                        <View>
                            <Image source={require("../../assets/phone_call_icon.png")}  style={{width:120,height:120}}/>
                        </View>
                        <Text style={styles.modalText}>На введенный номер телефона поступит звонок, введите последние 4 цифры входящего номера.</Text>
                        <TextInput
                            style={
                                validPincodeStatus
                                    ? validPincodeStatusGreen
                                        ? [styles.phoneInput, styles.codeInputSuccess]
                                        : [styles.phoneInput, styles.codeInputDefault]
                                    : [styles.phoneInput, styles.codeInputError]
                            }
                            onChangeText={(text) => checkPincode(text)}
                            maxLength={5}
                            value={pincodeNumber}
                            multiline={false}
                            textAlign={'center'}
                            keyboardType={Platform.OS === 'android' ? "phone-pad" : "phone-pad"}
                        />
                        {validPincodeStatusGreen ?
                            <View>
                                <ActivityIndicator size={29} color={THEME.MAIN_COLOR}/>
                            </View>
                            :
                            <Pressable
                                style={[styles.buttonCity,styles.refreshInputButton]}
                                onPress={() => {
                                    if(counter === 0) {
                                        setAuthStep('method');
                                    }
                                }}
                            >
                                <Text style={styles.textRefreshButton}>Получить код повторно {counter === 0 ? "" : <Text>{"\n"}через {format(counter)} мин</Text>}</Text>
                            </Pressable>
                        }
                    </View>
                    <View>
                        <Pressable
                            style={[styles.buttonCity, styles.buttonsSuccess]}
                            color={THEME.MAIN_COLOR}
                            onPress={() => {
                                window.location.hash = 'Catalog';
                                navigation.navigate('Catalog');
                            }}
                        >
                            <Text style={{color:"#fff"}}>Вернуться в каталог</Text>
                        </Pressable>
                    </View>
                </SafeAreaView>
            );
        }else{
            return (
                <SafeAreaView style={styles.centeredViewWindowTop}>
                    <View style={styles.modalView}>
                        <View>
                            <Image source={require("../../assets/phone_call_icon.png")}  style={{width:120,height:120}}/>
                        </View>
                        <Text style={styles.modalText}>Позвоните на бесплатный номер для подтверждения входа.</Text>
                        <a
                            href={getPhoneTelLink(reverseCallPhoneTo)}
                            onClick={(event) => handlePhoneDial(event, reverseCallPhoneTo)}
                            style={{fontSize:24,fontWeight:"700",marginTop:10,marginBottom:10,color:THEME.MAIN_COLOR,textAlign:"center",textDecoration:'none',display:'inline-block'}}
                        >
                            {formatPhoneForDisplay(reverseCallPhoneTo)}
                        </a>
                        <Text style={{textAlign:"center",fontSize:13,color:"#5b5b5b",lineHeight:20}}>
                            После успешного звонка авторизация произойдет автоматически.
                        </Text>
                        <Pressable
                            style={[styles.buttonCity,styles.refreshInputButton,{marginTop:20}]}
                            onPress={() => {
                                clearReverseCallPoll();
                                setAuthStep('method');
                                setReverseCallPhoneTo('');
                            }}
                        >
                            <Text style={styles.textRefreshButton}>Другие способы</Text>
                        </Pressable>
                    </View>
                    <View>
                        <Pressable
                            style={[styles.buttonCity, styles.buttonsSuccess]}
                            color={THEME.MAIN_COLOR}
                            onPress={() => {
                                window.location.hash = 'Catalog';
                                navigation.navigate('Catalog');
                            }}
                        >
                            <Text style={{color:"#fff"}}>Вернуться в каталог</Text>
                        </Pressable>
                    </View>
                </SafeAreaView>
            );
        }
    }

    if(CityLoadPhone){
    return (
            <SafeAreaView style={styles.centeredViewWindow}>
                <View style={styles.modalView}>
                    <Text style={styles.modalText}>Выберите город</Text>
                    {Object.keys(CityList).map((data,id)=>{
                        return(
                            <Pressable
                                style={styles.buttonCity}
                                onPress={() => {
                                        saveHandler(data,CityList[data]);
                                }}
                                key={"CityLink_"+id}
                            >
                                <Text style={styles.textStyle}>{CityList[data]}</Text>
                            </Pressable>
                        );
                    })}
                </View>
            </SafeAreaView>
        );
    } else {
        return null;
    }

    return null;
};

AuthorizationScreen.navigationOptions = ({ navigation, route }) => ({
    headerShown: false,
    headerTitle: 'Авторизация',
    headerLeft: (
        <HeaderButtons HeaderButtonComponent={AppHeaderIcon}>
            <Item
                title='Toggle Drawer'
                iconName='ios-menu'
                onPress={() => navigation.toggleDrawer()}
            />
        </HeaderButtons>
    )
});

