import React from 'react';
import {StyleSheet, Text, View} from 'react-native';
import {MaterialCommunityIcons} from '../../../components/SystemIcons';
import {THEME} from '../../../theme';
import {NumberFormatPrice} from '../../../templateComponents/NumberFormat/NumberFormat';
import {getNoun} from '../../../templateComponents/Noun/GetNoun';

const money = value => NumberFormatPrice(Number(value) || 0, 0, '.', ' ') + ' ₽';
const dateFromSeconds = value => {
    const seconds = Number(value);
    const date = new Date(seconds * 1000);
    return seconds > 0 && Number.isFinite(date.getTime()) ? date : null;
};
const formatDate = date => new Intl.DateTimeFormat('ru-RU', {
    day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit'
}).format(date);
const formatPreorderDate = value => {
    // Предзаказ приходит строкой местного времени, без преобразования часового пояса.
    const match = String(value).trim().match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})\s+(?:в\s+)?(\d{1,2}:\d{2})(?::\d{2})?$/);
    if (!match) return value;
    const months = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
        'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
    const month = months[Number(match[2]) - 1];
    return month ? `${Number(match[1])} ${month} ${match[3]} г. к ${match[4]}` : String(value).replace(/\sв\s/, ' к ');
};

export const OrderSummaryCard = ({order, productCount, sauceCount, personCountActive, paymentText, bonusActive, bonusText, section = 'info'}) => {
    if (!order) return null;
    const pickup = order.dilivery?.dilivery_type === 'Самовывоз';
    const address = pickup ? order.affiliate?.pickup?.affiliate_info : order.dilivery?.dilivery_adres;
    const meta = [productCount + ' ' + getNoun(productCount, 'товар', 'товара', 'товаров')];
    if (sauceCount > 0) meta.push(sauceCount + ' ' + getNoun(sauceCount, 'соус', 'соуса', 'соусов'));
    if (personCountActive && Number(order.person) > 0) meta.push(order.person + ' ' + getNoun(Number(order.person), 'персона', 'персоны', 'персон'));
    const bonus = value => value + ' ' + getNoun(Number(value), bonusText?.one || 'бонус', bonusText?.two || 'бонуса', bonusText?.five || 'бонусов');
    const preorder = order.pre_order?.status && order.pre_order.status !== 'none' && order.pre_order.date_pre_order;
    const created = dateFromSeconds(order.date_UNIXTIME);
    const deliveryDate = dateFromSeconds(order.date_UNIXTIME_delivered);
    const configuredMinutes = order.plusMinusMin == null ? NaN : Number(order.plusMinusMin);
    const minutes = Number.isFinite(configuredMinutes) && configuredMinutes >= 0 ? configuredMinutes : (preorder ? 20 : 15);
    let receivingTime = '';
    if (preorder) {
        receivingTime = formatPreorderDate(preorder) + (minutes > 0 ? ' ± ' + minutes + ' мин' : '');
    } else if (deliveryDate) {
        const end = new Date(deliveryDate.getTime() + minutes * 60000);
        receivingTime = new Intl.DateTimeFormat('ru-RU', {
            day: '2-digit', month: 'long', year: 'numeric'
        }).format(end) + ' до ' + new Intl.DateTimeFormat('ru-RU', {
            hour: '2-digit', minute: '2-digit'
        }).format(end);
    }
    const extras = [];
    if (!pickup) extras.push('Доставка ' + (Number(order.dilivery?.dilivery_price) > 0 ? money(order.dilivery.dilivery_price) : 'бесплатно'));
    if (Number(order.serviceFeeSum) > 0) extras.push('Сервисный сбор ' + money(order.serviceFeeSum));
    const bonuses = [];
    if (bonusActive && Number(order.point_in) > 0) bonuses.push('Начислено ' + bonus(order.point_in));
    if (bonusActive && Number(order.point_out) > 0) bonuses.push('Списано ' + bonus(order.point_out));
    return (
        <View style={styles.summary}>
            {section === 'info' ? <>
            {created ? <Text style={styles.created}>Заказан {formatDate(created)}</Text> : null}
            <View style={styles.logistics}>
                <MaterialCommunityIcons name={pickup ? 'storefront-outline' : 'map-marker-outline'} size={18} color="#737780" style={styles.icon}/>
                <View style={styles.content}>
                    <Text style={styles.sectionTitle}>{pickup ? 'Самовывоз' : 'Доставка'}</Text>
                    <Text style={styles.address}>{address || 'Адрес не указан'}</Text>
                    {receivingTime ? (
                        <Text style={[styles.time, {color: THEME.MAIN_COLOR}]}>
                            {preorder ? 'Предзаказ на ' : ''}{receivingTime}
                        </Text>
                    ) : null}
                </View>
            </View>
            <View style={styles.payment}>
                <MaterialCommunityIcons name="wallet-outline" size={18} color="#737780" style={styles.icon}/>
                <View style={styles.content}>
                    <Text style={styles.paymentText}>{paymentText}</Text>
                    {bonuses.length > 0 ? <Text style={styles.secondary}>{bonuses.join(' · ')}</Text> : null}
                </View>
            </View>
            </> : null}
            {section === 'totals' ? <View style={styles.receipt}>
                <View style={styles.totalRow}>
                    <View style={styles.content}>
                        <Text style={styles.sectionTitle}>Итого</Text>
                        <Text style={styles.secondary}>{meta.join(' · ')}</Text>
                    </View>
                    <Text style={styles.total}>{money(order.sum_order)}</Text>
                </View>
                {extras.length > 0 ? <Text style={styles.secondary}>{extras.join(' · ')} — включено</Text> : null}
                {Number(order.birthday_discount) > 0 ? (
                    <Text style={styles.discount}>Учтена скидка на день рождения <Text style={styles.discountAmount}>−{money(order.birthday_discount)}</Text></Text>
                ) : null}
                {order.promo && order.promo !== 'none' ? (
                    <Text style={styles.secondary}>Промокод: {[order.promo.promo_code, order.promo.promo_info?.title].filter(Boolean).join(' · ')}</Text>
                ) : null}
            </View> : null}
        </View>
    );
};

const styles = StyleSheet.create({
    summary: {marginHorizontal: '5%'},
    created: {fontSize: 11, lineHeight: 16, color: '#858991', marginBottom: 8},
    logistics: {flexDirection: 'row', alignItems: 'flex-start'},
    icon: {marginRight: 8, marginTop: 1},
    content: {flex: 1, minWidth: 0},
    sectionTitle: {fontSize: 12, lineHeight: 17, fontWeight: '600', color: '#25282e'},
    address: {fontSize: 12, lineHeight: 17, color: '#454951'},
    time: {fontSize: 11, lineHeight: 17, marginTop: 2},
    payment: {flexDirection: 'row', alignItems: 'flex-start', marginTop: 8},
    paymentText: {fontSize: 12, lineHeight: 17, color: '#454951'},
    secondary: {fontSize: 11, lineHeight: 16, color: '#7b7f87'},
    receipt: {marginTop: 9, paddingTop: 8, borderTopWidth: StyleSheet.hairlineWidth, borderTopColor: '#e9eaed'},
    totalRow: {flexDirection: 'row', alignItems: 'center', marginBottom: 3},
    total: {fontSize: 17, lineHeight: 22, fontWeight: '700', color: '#25282e', marginLeft: 10},
    discount: {fontSize: 11, lineHeight: 16, color: '#626770'},
    discountAmount: {fontWeight: '600', color: '#454951'}
});
